INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 3000, 2, 1000, "vo_minigame_1013_icon_2_002_001", "vo_minigame_1013_icon_1_002_001", "調子が上がって\nきたなっ", 2, "訓練はまだ\nここからですわ", 1);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 3000, 2, 5000, "vo_minigame_1013_icon_2_003_001", "vo_minigame_1013_icon_1_003_001", "ほらほら、\nまだいけるだろ？", 2, "クスクス、悪くない\n流れですわね", 2);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (2, 3000, 3, 10000, "vo_minigame_1013_icon_2_004_001", "vo_minigame_1013_icon_1_004_001", "へへっ、おまえら\nやるじゃねえか！", 2, "すばらしい\n記録ですわ", 3);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, 3000, 3, 10000, "vo_minigame_1013_icon_2_005_001", "vo_minigame_1013_icon_1_005_001", "あたしたちはまだ\n止まらねえぜ！", 2, "乗りに乗って\nいますわね", 4);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, 3000, 3, 10000, "vo_minigame_1013_icon_2_005_002", "vo_minigame_1013_icon_1_005_002", "見てろよ！\nマコト班の快進撃だ！", 2, "まだまだ行きます\nついてきなさい", 5);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (3, 3000, 3, 10000, "vo_minigame_1013_icon_2_005_003", "vo_minigame_1013_icon_1_005_003", "うおぉぉっ！\n絶好調だぜ！", 2, "エリコ班の\n本領発揮ですわ！", 6);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (4, 3000, 3, 0, "vo_minigame_1013_icon_2_006_001", "vo_minigame_1013_icon_1_006_001", "どこまで行けるか\n楽しみだなっ！", 2, "ここからは\n前人未到の領域です！", 7);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (5, 1000, 4, 1, "vo_minigame_1013_icon_2_007_001", "vo_minigame_1013_icon_1_007_001", "まだ諦めんなよっ", 3, "厄介でしたわ…", 8);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (5, 1000, 4, 1, "vo_minigame_1013_icon_2_007_002", "vo_minigame_1013_icon_1_007_002", "冷やっとしたぜ…！", 3, "油断大敵です", 9);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (5, 1000, 4, 1, "vo_minigame_1013_icon_2_007_003", "vo_minigame_1013_icon_1_007_003", "弱音を吐くなっ", 3, "忌々しいっ…", 10);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (6, 1500, 3, 99, "vo_minigame_1013_icon_2_008_001", "vo_minigame_1013_icon_1_008_001", "マコト班集合！", 4, "大所帯ですわね", 11);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (6, 1500, 3, 99, "vo_minigame_1013_icon_2_008_002", "vo_minigame_1013_icon_1_008_002", "連携してくぞ！", 4, "エリコ班へようこそ", 12);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (8, 3000, 6, 0, "vo_minigame_1013_icon_2_020_001", "vo_minigame_1013_icon_1_020_001", "みんなに力を！", 1, "ナナカちゃんに\nお任せあれ", 13);
INSERT INTO `v1_18ecb456cd6d9d74ef866b417282c14f15dace3577eb5ed9e728d0dafb77be99` VALUES (9, 3000, 7, 0, "vo_minigame_1013_icon_2_022_001", "vo_minigame_1013_icon_1_022_001", "任せてくれたまえ", 1, "はっはっは！\n任せろ！", 14);
